from lessons import L
L(10, 'String tools: length, positions, slices, methods', '🔤', 25,
  'Look inside text: count it, pick letters, cut pieces and change it with string methods.',
  ['I can use len() and know that spaces count', 'I can pick a letter with text[0] and text[-1]', 'I can cut a piece with text[a:b] and reverse with [::-1]',
   'I know methods like upper() give a NEW string, so I store the result'],
  [
  ('p', 'A username must be 8 letters or fewer. A password must not start with a space. A name must start with a capital. To check any of this, your program has to <b>look inside text</b>. Python gives you tools for that.'),
  ('h', '1. How long is it? len()'),
  ('p', '<code>len(text)</code> counts the characters in the text. <b>Spaces count too.</b> It returns an int.'),
  ('try', 'word = input("Word: ")\nprint(len(word))', ['planet'], 'Run it with <code>planet</code>. Then try <code>hi there</code> and count the space.'),
  ('h', '2. Positions: indexing'),
  ('p', 'Every character has a <b>position number</b>, called its <b>index</b>. Careful: Python starts counting at <b>0</b>, not 1. A negative index counts from the end.'),
  ('table', ['Letter', 'p', 'l', 'a', 'n', 'e', 't'], [
     ['Index', '0', '1', '2', '3', '4', '5'],
     ['From the end', '-6', '-5', '-4', '-3', '-2', '-1']]),
  ('show', 'word = "planet"\nprint(word[0])\nprint(word[2])\nprint(word[-1])\nprint(len(word))', []),
  ('rule', 'Positions start at 0', 'The first letter is <code>text[0]</code>. The last letter is <code>text[-1]</code>. A word with 6 letters has positions <b>0 to 5</b>, so the biggest index is <code>len(text) - 1</code>.'),
  ('trap', '<b>Off by one:</b> <code>word[6]</code> on "planet" does not exist. Python crashes with <b>IndexError</b>. The same goes for <code>word[len(word)]</code>.'),
  ('try', 'word = "planet"\nprint(word[3])\nprint(word[6])', [], 'Which letter is position 3? Run it. The second line crashes: read the error.'),
  ('quick', 'What is "robot"[1]?', ['o', 'r', 'b', 'Error'], 0, 'Position 0 is r, position 1 is o.'),
  ('h', '3. Cutting pieces: slicing'),
  ('p', 'A <b>slice</b> takes a piece: <code>text[a:b]</code> starts AT <code>a</code> and stops <b>BEFORE</b> <code>b</code>. The end number is never included.'),
  ('show', 'word = "rocket"\nprint(word[1:4])\nprint(word[:3])\nprint(word[2:])\nprint(word[::-1])', []),
  ('table', ['Slice', 'Means', 'Result on "rocket"'], [
     ['<code>word[1:4]</code>', 'positions 1, 2, 3', 'ock'],
     ['<code>word[:3]</code>', 'from the start, stop before 3', 'roc'],
     ['<code>word[2:]</code>', 'from 2 to the end', 'cket'],
     ['<code>word[::-1]</code>', 'everything, backwards', 'tekcor']]),
  ('trap', 'A <b>single index</b> can crash (<code>word[10]</code> is an IndexError), but a <b>slice never crashes</b>. <code>word[10:]</code> just gives empty text.'),
  ('h', '4. Methods: tools that belong to a string'),
  ('p', 'A <b>method</b> is a tool written after a dot: <code>text.upper()</code>. Here are the ones you need.'),
  ('table', ['Method', 'What it does', 'Example', 'Result'], [
     ['<code>upper()</code> / <code>lower()</code>', 'all capitals / all small', '<code>"Hi".upper()</code>', 'HI'],
     ['<code>title()</code>', 'Capital Letter On Each Word', '<code>"ada lovelace".title()</code>', 'Ada Lovelace'],
     ['<code>capitalize()</code>', 'only the first letter is a capital', '<code>"ada lovelace".capitalize()</code>', 'Ada lovelace'],
     ['<code>strip()</code>', 'removes spaces at both ends', '<code>"  hi  ".strip()</code>', 'hi'],
     ['<code>replace(a, b)</code>', 'swaps every a for b', '<code>"a-b".replace("-", " ")</code>', 'a b'],
     ['<code>count(x)</code>', 'how many times x appears', '<code>"banana".count("a")</code>', '3'],
     ['<code>find(x)</code>', 'position of the first x, or -1', '<code>"banana".find("n")</code>', '2'],
     ['<code>startswith(x)</code> / <code>endswith(x)</code>', 'True or False', '<code>"Python".startswith("Py")</code>', 'True'],
     ['<code>isdigit()</code> / <code>isalpha()</code>', 'only digits? / only letters?', '<code>"123".isdigit()</code>', 'True']]),
  ('try', 'text = "  Hello World  "\nprint(text.strip())\nprint(text.lower())\nprint(text.replace("o", "0"))\nprint(text.count("o"))', [], 'Predict each line first, then Run.'),
  ('show', 'print("banana".find("n"))\nprint("banana".find("z"))\nprint("12".isdigit())\nprint("1.5".isdigit())', []),
  ('p', '<code>find</code> does not crash when it finds nothing. It gives <b>-1</b>. That means "not found". Position 0 is a real position (the first letter), so do NOT use find as a True/False check.'),
  ('rule', 'Methods do NOT change the original', 'Strings cannot be changed. <code>text.upper()</code> makes a <b>new</b> string and the old one stays the same. To keep the new one, store it: <code>text = text.upper()</code>.'),
  ('try', 'name = "sam"\nname.upper()\nprint(name)\nname = name.upper()\nprint(name)', [], 'The first print shows the old name. Why? Run it and see.'),
  ('trap', '<b>You cannot change one letter.</b> <code>word[0] = "X"</code> is a <b>TypeError</b>. Build a new string instead: <code>word = "X" + word[1:]</code>.'),
  ('h', '5. Checking and combining'),
  ('p', 'The word <code>in</code> asks "is this piece inside that text?" and answers True or False. It is case-sensitive: <code>"A"</code> is not <code>"a"</code>. You can also glue with <code>+</code> and repeat with <code>*</code>.'),
  ('show', 'print("a" in "cat")\nprint("A" in "cat")\nprint("ab" + "cd")\nprint("ab" * 3)', []),
  ('p', 'A <code>for</code> loop can visit the letters of a word one at a time. Combine it with <code>in</code> to count vowels.'),
  ('trace', 'count = 0\nfor ch in "cat":\n    if ch in "aeiou":\n        count += 1\nprint(count)', []),
  ('try', 'text = input("Type digits: ")\nif text.isdigit():\n    print(int(text) + 1)\nelse:\n    print("That is not a number")', ['41'], 'Try <code>41</code>, then <code>4a</code>, then <code>2.5</code>. isdigit() protects int() from crashing.'),
  ('h', 'Common mistakes'),
  ('table', ['Mistake', 'What happens'], [
     ['<code>word[len(word)]</code> (off by one)', 'IndexError'],
     ['<code>word[0] = "X"</code> (changing a letter)', 'TypeError'],
     ['<code>name.upper()</code> alone, not stored', 'Nothing changes (no error)'],
     ['<code>"Age: " + len(name)</code> (text + number)', 'TypeError'],
     ['<code>int("12a")</code> (not all digits)', 'ValueError - check with isdigit() first'],
     ['<code>"A" in "cat"</code> (wrong case)', 'False - use lower() first']]),
  ('quick', 'What does print("hello"[1:3]) show?', ['el', 'ell', 'hel', 'he'], 0, 'Positions 1 and 2. It stops BEFORE 3.'),
  ('quick', 'name = "Zoe". Which line stores the capitals?', ['name = name.upper()', 'name.upper()', 'upper(name)', 'name[0] = "Z"'], 0, 'The new string must be stored back, or it is thrown away.'),
  ('quick', 'What does "cat".find("z") give?', ['-1', '0', 'False', 'Error'], 0, 'find never crashes. It gives -1 when there is no match.'),
  ])
